design.css:
/* [VIA:DESIGN:v0104] VeritasReportNova Workbench 範本 · VRN / VDF / VCGC 同一模板(顏色 · 字型 · 頁首 · 分頁 · 卡片 · 表格 · 動畫;值全來自 :root token · 燈四色不動) */
:root{--paper:var(--panel);--paper2:var(--chip);--ink:var(--txt);--mute:var(--dim);--co:var(--seal);--r:var(--radius)}
html body{background:var(--bg);color:var(--txt);font-family:var(--font)}
a{color:var(--blue)}
header,.top,.via-hd{position:relative;background:var(--head);color:var(--head-txt);border-bottom:1px solid var(--line)}
header::after,.top::after,.via-hd::after{content:"";position:absolute;left:0;right:0;bottom:-1px;height:4px;background:linear-gradient(90deg,var(--seal),var(--am),var(--blue),var(--teal));pointer-events:none}
header h1,.top h1,.via-brand{font-family:var(--serif);font-weight:800;font-size:var(--fs-title);letter-spacing:.2px;margin:1px 0 2px;color:var(--head-txt)}
header h1::before,header h1::after,.top h1::before,.top h1::after{content:none}
header small,.via-caption{display:block;font-family:var(--mono);font-size:var(--fs-note);font-weight:700;letter-spacing:2px;text-transform:uppercase;color:var(--dim)}
.meta{font-family:var(--mono);font-size:var(--fs-note);color:var(--mut2)}
aside,.side{background:var(--panel-2);border-color:var(--line)}
label,.dim,.via-note,.side label{color:var(--dim)}
.card,.kpi,.g3s,.side details,.chip{background:var(--panel);border:1px solid var(--line);border-radius:var(--radius);box-shadow:none;transition:border-color .18s}
.card:hover,.kpi:hover{border-color:var(--mut2)}
.card>b,.card h2,.hd,.side summary,.kpi b{color:var(--txt)}
button,.btn,.pages button,.sysbtn,.bar button,.fold-btn,#l121-fold{background:var(--panel);color:var(--ink2);border:1px solid var(--line);border-radius:6px;font-family:var(--font);font-weight:700;transition:background .15s,color .15s,border-color .15s}
button:hover,.btn:hover{background:var(--soft)}
.tabs button{font-family:var(--serif);font-weight:700;color:var(--dim);border-color:transparent;background:transparent}
.tabs button:hover{background:var(--soft);color:var(--ink2)}
button.p,.btn.pri,.tabs button.on,.tabs button.active,.pages button.on,.sysbtn.on{background:var(--ink);color:#fff;border-color:var(--ink);box-shadow:none}
.sysbtn.on small,.sysbtn.on b,.btn.pri small{color:#fff}
input,select,textarea{background:var(--panel);color:var(--txt);border:1px solid var(--line);border-radius:6px;font-family:var(--mono)}
table{background:var(--panel);border-collapse:collapse}
th{background:var(--chip);color:var(--mut2);border-bottom:1px solid var(--line);font-family:var(--mono);font-size:var(--fs-note);font-weight:500;letter-spacing:.1em;text-transform:uppercase;vertical-align:top}
td{border-bottom:1px solid var(--soft);vertical-align:top}
tr:nth-child(even) td{background:var(--zebra)}
tbody tr td{transition:background .15s}tbody tr:hover td{background:var(--soft)}
.seal{background:var(--seal);color:#fff}
@keyframes viaDown{from{opacity:0;transform:translateY(-6px)}to{opacity:1;transform:none}}
details[open]>*:not(summary),.detail-panel.open,.sm-detail{animation:viaDown .2s ease}
